for key, values in extras.items():
    base[key] = values[0]
    for locale, value in zip(['si','ta','hi','ar','fr','zh-Hans'],values[1:]): TRANSLATIONS[locale][key] = value
strings = {}
for key,value in base.items():
    local = {'en': {'stringUnit': {'state':'translated','value':value}}}
    for locale,words in translations.items():
        translated = dict(zip(keys,words))
        translated['trashWarning'] = safety[locale]
        translated.update(TRANSLATIONS[locale])
        if key in translated: local[locale] = {'stringUnit': {'state':'needs_review','value':translated[key]}}
    strings[key] = {'extractionState':'manual','localizations':local}
path = Path(__file__).resolve().parents[1]/'SpaceMithra/Localization/Localizable.xcstrings'
path.write_text(json.dumps({'sourceLanguage':'en','strings':strings,'version':'1.0'},ensure_ascii=False,indent=2)+'\n')
print(f'{len(strings)} localization keys; untranslated text uses English fallback')
